import 'dart:convert';

import '../../lowering/plans.dart';

/// Generates a concrete public-interop bridge, never a schema interpreter.
String emitDart(ModulePlan module) {
  final out = StringBuffer(
    '''// Generated by napi's foundation fixture compiler.
import 'dart:js_interop';
import 'package:napi/runtime.dart' as runtime;
import ${_dartString(module.sourceUri.toString())} as source;

class ModuleBridge {
''',
  );
  for (var index = 0; index < module.calls.length; index++) {
    final call = module.calls[index];
    final parameters = <String>[];
    final arguments = <String>[];
    for (var i = 0; i < call.arguments.length; i++) {
      final operation = call.arguments[i].operation;
      parameters.add('${_transport(operation)} a$i');
      arguments.add('a$i.${_decode(operation)}');
    }
    out.writeln('  @JSExport()');
    out.writeln(
      '  JSObject c$index(${parameters.join(', ')}) => runtime.guard(() {',
    );
    final invocation =
        'source.${call.binding.dartName}(${arguments.join(', ')})';
    switch (call.result.operation) {
      case ConversionOperation.voidToJs:
        out.writeln('    $invocation;\n    return null;');
      case ConversionOperation.safeIntegerToJs:
        out.writeln(
          '    return runtime.checkedIntOutput($invocation, ${_dartString('${call.binding.publicName} return value')}).toJS;',
        );
      case ConversionOperation.doubleToJs:
      case ConversionOperation.booleanToJs:
      case ConversionOperation.stringToJs:
        out.writeln('    return ($invocation).toJS;');
      default:
        throw StateError('Input operation used for a result');
    }
    out.writeln('  });');
  }
  out.writeln('''}

void main(List<String> arguments) {
  runtime.registerBindings(arguments, createJSInteropWrapper(ModuleBridge()));
}
''');
  return out.toString();
}

String _transport(ConversionOperation operation) => switch (operation) {
  ConversionOperation.safeIntegerFromJs ||
  ConversionOperation.doubleFromJs => 'JSNumber',
  ConversionOperation.booleanFromJs => 'JSBoolean',
  ConversionOperation.stringFromJs => 'JSString',
  _ => throw StateError('Output operation used for a parameter'),
};

String _decode(ConversionOperation operation) => switch (operation) {
  ConversionOperation.safeIntegerFromJs => 'toDartInt',
  ConversionOperation.doubleFromJs => 'toDartDouble',
  ConversionOperation.booleanFromJs ||
  ConversionOperation.stringFromJs => 'toDart',
  _ => throw StateError('Output operation used for a parameter'),
};

String _dartString(String value) => jsonEncode(value).replaceAll(r'$', r'\$');
